// Parameterised conversation-log miner: node mine.mjs <file.jsonl> [mode]
// mode: human (default, real user turns) | time (slowest tool calls + wall clock)
import fs from 'node:fs';

const [file, mode = 'human'] = process.argv.slice(2);
const lines = fs.readFileSync(file, 'utf8').trim().split('\n');
const es = [];
for (const l of lines) { try { es.push(JSON.parse(l)); } catch {} }

const txt = (c) => Array.isArray(c)
  ? c.filter((b) => b.type === 'text').map((b) => b.text).join('\n')
  : (typeof c === 'string' ? c : '');

if (mode === 'human') {
  for (const e of es) {
    if (e.type !== 'user' || e.message?.role !== 'user') continue;
    const c = e.message.content;
    if (Array.isArray(c) && c.some((b) => b.type === 'tool_result')) continue;
    const t = txt(c).trim();
    if (!t) continue;
    console.log(`\n----- ${e.timestamp}\n${t.slice(0, 4000)}`);
  }
} else {
  const starts = new Map(); // tool_use_id -> {t, name, input}
  for (const e of es) {
    if (e.type === 'assistant') {
      for (const b of e.message?.content ?? []) {
        if (b.type === 'tool_use') starts.set(b.id, { t: Date.parse(e.timestamp), name: b.name, input: JSON.stringify(b.input).slice(0, 220) });
      }
    }
  }
  const spans = [];
  for (const e of es) {
    if (e.type !== 'user') continue;
    for (const b of (Array.isArray(e.message?.content) ? e.message.content : [])) {
      if (b.type !== 'tool_result') continue;
      const s = starts.get(b.tool_use_id);
      if (!s) continue;
      spans.push({ sec: Math.round((Date.parse(e.timestamp) - s.t) / 1000), name: s.name, input: s.input });
    }
  }
  const ts = es.map((e) => Date.parse(e.timestamp)).filter(Boolean);
  console.log(`wall clock: ${Math.round((Math.max(...ts) - Math.min(...ts)) / 60000)} min, ${spans.length} tool calls`);
  const byName = {};
  for (const s of spans) { byName[s.name] = (byName[s.name] ?? 0) + s.sec; }
  console.log('seconds by tool:', Object.entries(byName).sort((a, b) => b[1] - a[1]).slice(0, 12));
